INSERT INTO public.career_paths (domain, title, slug, description, overview, trajectory, salary_entry, salary_mid, salary_senior, perks, impact, exposure, eligibility, skills_needed, upsc_skill_mapping, difficulty_rating, growth_rate, courses, certifications, portfolio_projects, launchpad_weeks, estimated_cost, how_to_apply, youtube_links, podcast_links, professional_associations) VALUES

-- Domain 1 (continued)
('Policy, Governance & Public Affairs', 'Election/Political Analyst', 'election-political-analyst',
'Analyze electoral data, political trends, and campaign strategy for parties, media, and research organizations.',
'Political analysts decode election outcomes, forecast voting patterns, and advise campaigns. India''s massive and complex electoral system creates huge demand for people who understand political economy, caste dynamics, and voter behaviour. UPSC aspirants who studied polity and political science are naturally positioned for this.',
'[{"stage":"Entry","title":"Research Analyst","years":"0-2","salary":"₹4-8 LPA","responsibilities":["Voter data analysis","Survey design and execution","Report writing","Media briefings support"]},{"stage":"Mid","title":"Political Analyst","years":"2-5","salary":"₹8-18 LPA","responsibilities":["Election forecasting","Campaign strategy advisory","TV commentary","Polling management"]},{"stage":"Senior","title":"Senior Political Consultant","years":"5-10","salary":"₹18-40 LPA","responsibilities":["State-level campaign leadership","Party advisory","National media presence","Research organization leadership"]},{"stage":"Leadership","title":"Principal Strategist / Founder","years":"10+","salary":"₹40-100 LPA","responsibilities":["National campaign leadership","Think tank leadership","International advisory","Media brand"]}]',
'₹4-8 LPA', '₹8-18 LPA', '₹40-100 LPA',
ARRAY['Exciting work during elections', 'TV appearances', 'National visibility', 'Flexible work', 'Political access'],
'Shape how democracy functions by bringing rigorous analysis to electoral coverage and campaign strategy.',
'TV panels, senior political access, election rooms — some of the most exciting environments in India during election season.',
'Any graduate degree. Political science, economics, or sociology background preferred. Data skills increasingly important.',
ARRAY['Psephology', 'Survey design', 'Statistical analysis', 'Political knowledge', 'Communication', 'Data visualization', 'Media presence'],
'UPSC preparation provides comprehensive knowledge of Indian political systems, electoral laws, constitutional provisions, and political history. Your understanding of voter demographics, caste dynamics, and regional politics from GS Paper 2 is directly applicable.',
3, 'High - election cycle creates massive demand every 3-5 years',
'[{"name":"Political Data Analytics","provider":"CSDS Delhi","url":"https://www.lokniti.org","cost":"₹10,000","duration":"2 months"},{"name":"Survey Research Methods","provider":"Michigan (Coursera)","url":"https://www.coursera.org","cost":"Free audit","duration":"4 weeks"}]',
ARRAY['Certificate in Survey Research', 'Google Data Analytics Certificate'],
ARRAY['Election result analysis for 3 recent assembly elections', 'Voter behavior model using open TCPD data', 'State-level political landscape report'],
'[{"week":1,"title":"Foundation","tasks":["Download TCPD (Trivedi Centre for Political Data) datasets","Study Lokniti surveys and methodology","Read 3 Psephology books: Who Wins Elections, Indian Elections"]},{"week":2,"title":"Data Skills","tasks":["Learn to work with election commission data","Practice R or Python for electoral analysis","Visualize constituency-level vote share data"]},{"week":3,"title":"Research Organizations","tasks":["Apply to CSDS, Lokniti, ADR (Association for Democratic Reforms)","Connect with Yogendra Yadav alumni network","Apply to ABP, NDTV, CNN-News18 election units"]},{"week":4,"title":"Media Presence","tasks":["Write 3 election analysis pieces for Medium or NewsLaundry","Pitch to print media for election columns","Build Twitter presence as election analyst"]},{"week":5,"title":"Survey Design","tasks":["Learn questionnaire design basics","Study sampling methodology","Practice designing a voter survey","Understand CATI and field survey operations"]},{"week":6,"title":"Campaign Advisory","tasks":["Research political consulting firms (I-PAC, Prashant Kishor network)","Understand campaign data operations","Study micro-targeting and voter outreach strategies","Apply to campaign strategy roles"]},{"week":7,"title":"TV Commentary Prep","tasks":["Practice speaking on camera for 5 minutes on election topics","Build media kit and headshot","Pitch to TV channels as election expert","Join ABP, NDTV, Republic panel lists"]},{"week":8,"title":"Model Building","tasks":["Build a simple seat-share forecast model","Publish predictions with methodology","Track accuracy for credibility building","Use historical data from ECI website"]},{"week":9,"title":"State Specialization","tasks":["Choose 2 states to become expert in","Study caste demography, alliance history, economic data","Write comprehensive state analysis","Build contacts with state-level political reporters"]},{"week":10,"title":"Network","tasks":["Attend 2 political science conferences","Join IPSA or APSA student membership","Connect with academic political scientists","Build bipartisan network"]},{"week":11,"title":"Publication","tasks":["Submit paper to Economic and Political Weekly","Pitch to The Hindu, Indian Express for analysis pieces","Build reputation for rigorous non-partisan analysis","Create online portfolio of published work"]},{"week":12,"title":"Launch","tasks":["Final push applications to media and research orgs","Set up consulting for election season","Negotiate terms for campaign advisory roles","Build 6-month plan around election calendar"]}]',
'₹5,000-15,000',
'Apply to CSDS, Lokniti, ADR, and media organizations. Also approach political consulting firms (I-PAC) directly.',
'[{"title":"Lokniti Programme","url":"https://www.youtube.com/@lokniti","channel":"Lokniti-CSDS"},{"title":"The Print Politics","url":"https://www.youtube.com/@ThePrint","channel":"The Print"}]',
'[{"title":"Outlook Politics Podcast","url":"https://www.outlookindia.com/podcast","host":"Outlook India"}]',
ARRAY['Lokniti-CSDS', 'Association for Democratic Reforms (ADR)', 'Indian Political Science Association']),

('Policy, Governance & Public Affairs', 'Urban Planning & Smart Cities Consultant', 'urban-planning-smart-cities',
'Advise cities and governments on urban development, housing, infrastructure, and smart city initiatives.',
'India''s rapid urbanization creates massive demand for urban planning professionals. Smart Cities Mission, AMRUT, and RERA have created an ecosystem of consulting opportunities. UPSC aspirants who studied urban governance and geography are well-positioned.',
'[{"stage":"Entry","title":"Urban Research Associate","years":"0-2","salary":"₹4-8 LPA","responsibilities":["GIS mapping and analysis","Field surveys","Research reports","Municipal data analysis"]},{"stage":"Mid","title":"Urban Planner / Consultant","years":"2-5","salary":"₹8-16 LPA","responsibilities":["Master plan preparation","Smart city project management","Stakeholder consultations","Government reports"]},{"stage":"Senior","title":"Senior Urban Consultant","years":"5-10","salary":"₹16-30 LPA","responsibilities":["City-level project leadership","Technical advisory to municipal corporations","International project experience"]},{"stage":"Leadership","title":"Urban Planning Director","years":"10+","salary":"₹30-60 LPA","responsibilities":["Firm leadership","National urban policy advisory","World Bank/ADB project leadership"]}]',
'₹4-8 LPA', '₹8-16 LPA', '₹30-60 LPA',
ARRAY['Field visits to cities', 'Government access', 'International project opportunities', 'Diverse work', 'Intellectual challenge'],
'Shape how India''s cities grow — housing, transportation, public spaces, and services for millions of urban residents.',
'Work with municipal commissioners, state urban development departments, World Bank, and ADB.',
'Masters in Urban Planning (CEPT, SPA) preferred. Geography or civil engineering background also valued.',
ARRAY['GIS (QGIS/ArcGIS)', 'Urban policy knowledge', 'Data analysis', 'Report writing', 'Stakeholder management', 'Master plan reading'],
'UPSC Geography optional and GS Paper 1 (Urbanization) directly maps to urban planning. Your knowledge of urban local bodies, smart cities mission, and RERA from GS Paper 2 is immediately applicable.',
3, 'High - India urbanizing rapidly with massive infrastructure investment',
'[{"name":"GIS for Urban Planning","provider":"Esri (Coursera)","url":"https://www.coursera.org/learn/gis","cost":"Free audit","duration":"4 weeks"},{"name":"Urban Planning Fundamentals","provider":"Massachusetts Institute of Technology (MIT OCW)","url":"https://ocw.mit.edu","cost":"Free","duration":"Self-paced"}]',
ARRAY['GIS Professional Certification (GISP)', 'RICS Associate (urban planning pathway)', 'LEED AP BD+C'],
ARRAY['GIS analysis of a city''s green cover', 'Master plan review for a tier-2 city', 'Smart city dashboard prototype'],
'[{"week":1,"title":"GIS Foundation","tasks":["Download QGIS (free)","Complete 3 GIS tutorials on YouTube","Download census and city data for your city","Create a simple thematic map"]},{"week":2,"title":"Urban Policy Deep Dive","tasks":["Read Smart Cities Mission guidelines","Study AMRUT 2.0 framework","Read RERA and its impact on urban development","Study National Urban Policy 2018"]},{"week":3,"title":"Organizations to Target","tasks":["Research NIUA (National Institute of Urban Affairs)","Apply to urban consulting firms (IPLT, IMC Worldwide, AECOM India)","Apply to Smart City SPVs as project associates","Check World Bank, ADB India vacancies"]},{"week":4,"title":"First Project","tasks":["Volunteer on a local municipal initiative","Do a case study of your city''s master plan","Interview municipal officials","Write a report on urban issues in your city"]},{"week":5,"title":"Technical Skills","tasks":["Learn AutoCAD basics (free student version)","Practice reading development control regulations","Study FSI/FAR concepts","Understand zoning and land use planning"]},{"week":6,"title":"Masters Planning","tasks":["Research CEPT Ahmedabad, SPA Delhi urban planning programs","Apply if feasible — it significantly accelerates the career","Research scholarships for urban planning studies","Look at part-time/online programs"]},{"week":7,"title":"Research and Publication","tasks":["Write a paper on a specific urban issue","Submit to Urban India (NIUA journal)","Build GIS portfolio with 3 maps","Create LinkedIn content on urban topics"]},{"week":8,"title":"Network","tasks":["Join Indian Institute of Human Settlement (IIHS) events","Connect with NIUA alumni","Attend Urban Thinkers Campus events","Join ITDP India working group"]},{"week":9,"title":"Smart City Focus","tasks":["Study smart city case studies: Surat, Pune, Ahmedabad","Learn about IoT applications in city management","Study traffic management and data platforms","Connect with smart city SPV officials"]},{"week":10,"title":"International Exposure","tasks":["Apply to World Bank India urban team consultancies","Research Cities Alliance, ICLEI opportunities","Study international urban planning models","Apply for urban fellowship programs"]},{"week":11,"title":"Portfolio Build","tasks":["Complete 3 GIS projects","Write 2 urban analysis reports","Create a comprehensive portfolio document","Build LinkedIn profile as urban professional"]},{"week":12,"title":"Launch","tasks":["Apply to 10 urban consulting organizations","Follow up on government roles (town planning departments)","Negotiate contract rates for freelance urban consulting","Set CEPT/SPA application goals"]}]',
'₹10,000-30,000 (GIS software, courses)',
'Apply to urban consulting firms, Smart City SPVs, NIUA, and multilateral organizations working on India''s urban sector. Masters from CEPT Ahmedabad significantly accelerates the career.',
'[{"title":"NIUA Knowledge Hub","url":"https://www.youtube.com/@NIUAIndia","channel":"NIUA India"},{"title":"Smart Cities India","url":"https://www.youtube.com/@SmartCitiesIndia","channel":"Smart Cities Mission"}]',
'[{"title":"City Unseen Podcast","url":"https://cityunseen.in","host":"Urban practitioners"}]',
ARRAY['Institute of Town Planners India (ITPI)', 'National Institute of Urban Affairs (NIUA)', 'IIHS Alumni Network']),

-- Domain 2 (continued)
('Law & Legal Services', 'Legal Research & Compliance Associate', 'legal-research-compliance',
'Conduct legal research and manage regulatory compliance for law firms, companies, or government agencies.',
'Legal research and compliance is an accessible entry into the legal profession without mandatory litigation experience. Many companies, think tanks, and legal tech firms hire people with strong research and writing skills for compliance, regulatory tracking, and legal knowledge management.',
'[{"stage":"Entry","title":"Legal Research Associate","years":"0-2","salary":"₹4-9 LPA","responsibilities":["Case law research","Regulatory tracking","Compliance documentation","Legal database management"]},{"stage":"Mid","title":"Compliance Manager","years":"2-5","salary":"₹9-18 LPA","responsibilities":["Compliance program management","Regulatory filings","Legal risk assessment","Training programs"]},{"stage":"Senior","title":"Senior Compliance Manager","years":"5-8","salary":"₹18-35 LPA","responsibilities":["Compliance strategy","Regulatory advocacy","Board reporting","Audit management"]},{"stage":"Leadership","title":"Chief Compliance Officer","years":"8+","salary":"₹35-80 LPA","responsibilities":["Enterprise compliance leadership","Board-level reporting","Crisis management","Regulatory engagement"]}]',
'₹4-9 LPA', '₹9-18 LPA', '₹35-80 LPA',
ARRAY['Work-life balance vs litigation', 'Stable employment', 'Corporate benefits', 'Professional development', 'Growing field'],
'Protect organizations and citizens from regulatory violations and ensure fairness in commercial practices.',
'Work with regulators, legal teams, and senior management. Cross-functional exposure in large organizations.',
'LLB degree preferred. Strong research and writing skills. Compliance roles also accessible to non-lawyers with domain expertise.',
ARRAY['Legal research', 'Regulatory knowledge', 'Report writing', 'Risk assessment', 'Attention to detail', 'Communication', 'Database skills'],
'UPSC preparation builds exceptional legal research skills through constitutional law, administrative law, and procedural law study. Your understanding of regulatory frameworks across sectors (banking, environment, competition law) from GS Paper 3 is directly applicable.',
2, 'Very high - compliance demand growing with increasing regulatory complexity',
'[{"name":"Regulatory Compliance Management","provider":"ICSI","url":"https://www.icsi.edu","cost":"₹10,000","duration":"3 months"},{"name":"Legal Research Methods","provider":"Vidhi Centre for Legal Policy","url":"https://vidhilegalpolicy.in","cost":"₹5,000","duration":"2 months"}]',
ARRAY['Compliance and Ethics Professional (CCEP)', 'Certificate in Regulatory Affairs'],
ARRAY['Regulatory compliance checklist for a fintech startup', 'Data protection audit framework', 'Competition law compliance guide'],
'[{"week":1,"title":"Legal Research Foundation","tasks":["Learn SCC Online and Manupatra navigation","Study 10 landmark regulatory cases","Practice writing legal research memos","Study statutory interpretation methods"]},{"week":2,"title":"Compliance Domain","tasks":["Choose a compliance domain: data protection, SEBI, FEMA, environment","Read all key statutes in that domain","Study PDPB/DPDPA for data compliance","Read competition law basics"]},{"week":3,"title":"Target Organizations","tasks":["Apply to law firms with compliance practices","Apply to in-house legal/compliance teams","Apply to Vidhi Centre for Legal Policy","Apply to PRS or DAKSH for legal research roles"]},{"week":4,"title":"Writing Skills","tasks":["Write a regulatory compliance brief","Draft a RERA compliance checklist","Create a SEBI compliance calendar","Practice writing clear non-legal summaries of legal issues"]},{"week":5,"title":"Regulatory Authorities","tasks":["Study RBI, SEBI, TRAI, CCI, and their enforcement actions","Read 10 regulatory orders","Understand appeal mechanisms","Practice analyzing regulatory decisions"]},{"week":6,"title":"Legal Tech","tasks":["Learn Kira Systems or similar contract review tools","Study legal research AI platforms","Learn document management for legal teams","Build tech-forward legal profile"]},{"week":7,"title":"Applications","tasks":["Apply to 15 compliance and legal research roles","Focus on fintech, healthcare, and environmental sectors","Apply to law firms with regulatory practices","Prepare writing samples"]},{"week":8,"title":"Certifications","tasks":["Register for CCEP or IAPP certification","Study compliance frameworks: ISO 19600","Prepare for certification exams","Build CPE (continuing professional education) plan"]},{"week":9,"title":"Network","tasks":["Join Compliance Officers Network India","Connect with regulatory professionals on LinkedIn","Attend FICCI, CII compliance workshops","Request 3 informational interviews"]},{"week":10,"title":"Specialize","tasks":["Deep dive into one regulatory area","Read enforcement cases and orders","Write analysis of a recent regulatory action","Build reputation as domain expert"]},{"week":11,"title":"Build Profile","tasks":["Write LinkedIn articles on compliance topics","Comment on regulatory developments","Share analysis publicly","Build network of compliance professionals"]},{"week":12,"title":"Close","tasks":["Accept best offer","Negotiate salary with market benchmarks","Join professional compliance association","Set 1-year specialization goals"]}]',
'₹5,000-15,000',
'Apply to law firms with regulatory practice groups, in-house legal teams, legal tech companies, and research organizations like Vidhi Centre for Legal Policy, DAKSH, and PRS.',
'[{"title":"Vidhi Centre for Legal Policy","url":"https://www.youtube.com/@vidhilegalpolicy","channel":"Vidhi Centre"},{"title":"Bar & Bench","url":"https://www.youtube.com/@barandbench","channel":"Bar & Bench"}]',
'[{"title":"Legal Compliance Podcast","url":"https://compliancecast.in","host":"Indian compliance professionals"}]',
ARRAY['Society of Compliance and Ethics', 'Compliance Officers Network India', 'IAPP India Chapter']),

('Law & Legal Services', 'Legal Tech Professional', 'legal-tech-professional',
'Build, implement, and manage technology solutions for the legal industry — document automation, AI-assisted research, and legal operations.',
'Legal tech is one of the fastest-growing intersections of two massive industries. India''s legal sector is adopting technology rapidly — from e-courts to contract automation. For UPSC aspirants with legal backgrounds and tech curiosity, this is a lucrative and pioneering career path.',
'[{"stage":"Entry","title":"Legal Tech Analyst","years":"0-2","salary":"₹5-10 LPA","responsibilities":["Legal software implementation","User training","Process documentation","Legal data management"]},{"stage":"Mid","title":"Legal Operations Manager","years":"2-5","salary":"₹10-20 LPA","responsibilities":["Legal tech stack management","Process optimization","Vendor management","Analytics dashboards"]},{"stage":"Senior","title":"Legal Tech Director","years":"5-8","salary":"₹20-40 LPA","responsibilities":["Legal operations strategy","AI implementation","Budget management","Cross-functional leadership"]},{"stage":"Leadership","title":"Chief Legal Operations Officer","years":"8+","salary":"₹40-90 LPA","responsibilities":["Legal operations transformation","Board advisory","Tech-law strategy","Innovation leadership"]}]',
'₹5-10 LPA', '₹10-20 LPA', '₹40-90 LPA',
ARRAY['High growth sector', 'Tech industry compensation', 'Innovation environment', 'Remote work possible', 'International opportunities'],
'Democratize access to justice through technology. Make legal services faster, cheaper, and more accessible for ordinary people.',
'Work at the intersection of law, technology, and business. Access to cutting-edge AI and legal innovation.',
'LLB preferred. Tech interest and basic digital skills required. Product or consulting experience valuable.',
ARRAY['Legal domain knowledge', 'Product thinking', 'Data analysis', 'Process design', 'Communication', 'SQL basics', 'Project management'],
'UPSC preparation gives you deep legal domain knowledge which is the primary qualification gap for legal tech roles. Understanding of court systems, legal procedures, and regulatory frameworks from polity and law preparation is directly valuable.',
3, 'Very high - fastest growing segment of the legal market',
'[{"name":"Legal Operations Fundamentals","provider":"CLOC (Corporate Legal Operations Consortium)","url":"https://cloc.org","cost":"Free membership","duration":"Self-paced"},{"name":"Product Management Basics","provider":"Google (Coursera)","url":"https://www.coursera.org","cost":"Free audit","duration":"6 weeks"}]',
ARRAY['Certified Legal Manager (CLM)', 'CLOC Member Certification', 'Salesforce Legal Cloud Certification'],
ARRAY['Map the e-courts technology stack in India', 'Design a contract automation workflow', 'Legal chatbot prototype using no-code tools'],
'[{"week":1,"title":"Legal Tech Landscape","tasks":["Research legal tech startups in India: Legasis, SpotDraft, Leegality, Sirion Labs","Study e-courts project in India","Read about AI in legal research","Subscribe to Legal Tech Blog and Legaltech News"]},{"week":2,"title":"Tech Skills","tasks":["Learn basic SQL for legal data queries","Set up and explore Notion or Airtable for legal knowledge management","Try SpotDraft or DocuSign free trials","Learn contract automation concepts"]},{"week":3,"title":"Legal Operations","tasks":["Study CLOC (Corporate Legal Operations Consortium) framework","Learn KPIs for legal departments","Practice building a legal matter tracking system","Study legal spend management"]},{"week":4,"title":"Target Organizations","tasks":["Apply to legal tech startups in India","Apply to law firm technology departments","Apply to Big 4 legal managed services teams","Research Elevate, UnitedLex, and similar ALSPs"]},{"week":5,"title":"Product Thinking","tasks":["Take a free product management course","Learn to write user stories for legal workflows","Study legal UX design principles","Practice wireframing a legal app"]},{"week":6,"title":"AI in Law","tasks":["Explore Harvey AI, Kira Systems, Luminance","Study how AI is used for contract review","Understand LegalBench and LLM evaluation in legal context","Write analysis of AI legal tools"]},{"week":7,"title":"Court Technology","tasks":["Study India''s e-Courts Mission Phase 3","Research virtual courts and video conferencing","Explore eCourts API and data","Write a paper on legal tech in Indian judiciary"]},{"week":8,"title":"Interviews","tasks":["Prepare for product and analytical interviews","Practice product design questions for legal tools","Research companies deeply","Prepare portfolio of legal tech projects"]},{"week":9,"title":"Network","tasks":["Join Legal Founders India on LinkedIn","Attend LegalTech India events","Connect with legal startup founders","Offer free consulting to a legal startup"]},{"week":10,"title":"Build a Legal Tool","tasks":["Build a simple contract review checklist tool in Notion","Create a legal research database in Airtable","Share it with 5 lawyers for feedback","Iterate based on feedback"]},{"week":11,"title":"Thought Leadership","tasks":["Write LinkedIn articles on legal tech in India","Comment on legal tech developments","Build Twitter presence on legal tech","Get published in Bar & Bench or Live Law"]},{"week":12,"title":"Launch","tasks":["Accept best offer","Join CLOC or equivalent","Set learning goals for tech skills development","Plan side project or consulting"]}]',
'₹10,000-25,000',
'Apply to legal tech startups (SpotDraft, Leegality, Legasis), law firm tech departments, and Big 4 legal managed services. LinkedIn is the best source.',
'[{"title":"Legal Tech India","url":"https://www.youtube.com/@legaltechindia","channel":"Legal Tech India"},{"title":"Future Law","url":"https://www.youtube.com/@FutureLaw","channel":"Future Law"}]',
'[{"title":"CLOC Podcast","url":"https://cloc.org/podcast","host":"CLOC"}]',
ARRAY['CLOC (Corporate Legal Operations Consortium)', 'Legal Tech Association of India', 'International Legal Technology Association (ILTA)']),

