('Psychology & Counseling', 'Organizational Psychologist / HR Consultant', 'org-psychologist-hr-consultant',
'Apply psychological principles to improve workplace performance, culture, and employee wellbeing.',
'Organizational psychology applies behavioral science to business challenges — selection, motivation, leadership, and culture. With a Masters in Organizational Psychology or Industrial-Organizational Psychology, UPSC aspirants can build highly rewarding careers in HR consulting, leadership assessment, and organizational development.',
'[{"stage":"Entry","title":"HR Analyst / Assessment Associate","years":"0-2","salary":"₹4-9 LPA","responsibilities":["Psychometric assessment administration","HR data analysis","Training support","Survey design"]},{"stage":"Mid","title":"Organizational Development Consultant","years":"2-5","salary":"₹9-20 LPA","responsibilities":["Leadership assessment","Culture diagnostics","OD interventions","Training facilitation"]},{"stage":"Senior","title":"Senior OD Manager / Consulting Lead","years":"5-8","salary":"₹20-40 LPA","responsibilities":["OD strategy","Executive coaching","Large-scale organizational interventions","Consulting practice building"]},{"stage":"Leadership","title":"VP HR / Practice Head","years":"8+","salary":"₹40-90 LPA","responsibilities":["People strategy","Board advisory","Research leadership","Consulting firm management"]}]',
'₹4-9 LPA', '₹9-20 LPA', '₹40-90 LPA',
