'[{"week":1,"title":"OD Foundation","tasks":["Study key OD models: Action Research, Appreciative Inquiry, McKinsey 7S","Read Edgar Schein on organizational culture","Study Denison Organizational Culture Survey","Subscribe to OD Network publications"]},{"week":2,"title":"Masters Planning","tasks":["Research IOPs programs: XLRI, TISS, Banaras Hindu University","Research international programs: UCL, Lund, SIOP-affiliated schools","Apply if feasible — Masters significantly accelerates","Look at online masters programs as alternatives"]},{"week":3,"title":"HR Analytics","tasks":["Learn HR analytics fundamentals","Study people data: attrition, engagement, performance","Practice analyzing HR datasets","Build HR dashboard in Excel or Power BI"]},{"week":4,"title":"Assessment Tools","tasks":["Study major psychometric tools: MBTI, Hogan, Big Five, DISC","Understand 16PF and OPQ","Practice using free assessment tools","Learn about structured behavioral interviewing"]},{"week":5,"title":"Target Organizations","tasks":["Apply to HR consulting firms: Mercer, Aon Hewitt, Hay Group, Korn Ferry","Apply to organizational development teams at large companies","Apply to assessment centers","Apply to L&D consulting organizations"]},{"week":6,"title":"Coaching Certification","tasks":["Enroll in ICF coaching certification program","Complete coaching log hours","Practice coaching with 5 coachees","Build coaching portfolio"]},{"week":7,"title":"OD Interventions","tasks":["Design a team effectiveness workshop","Facilitate a sample team diagnostic session","Practice culture assessment methodology","Build intervention design portfolio"]},{"week":8,"title":"Ethics Foundation","tasks":["Study UPSC GS Paper 4 (Ethics) connection to org behavior","Apply ethical frameworks to organizational challenges","Study whistleblowing, conflict of interest, bias in assessments","Build ethical practice guidelines"]},{"week":9,"title":"Research Skills","tasks":["Design an employee engagement survey","Practice survey analysis with SPSS or R","Write a research report on a people issue","Submit to Indian Journal of Industrial Relations"]},{"week":10,"title":"Network","tasks":["Join NHRDN (National HRD Network)","Attend SHRM India conference","Connect with I-O psychologists on LinkedIn","Build mentor relationships in OD space"]},{"week":11,"title":"Consulting Launch","tasks":["Create consulting service offerings","Define niche: culture assessment, leadership development, team effectiveness","Approach small businesses for first consulting engagements","Build a case study from pro bono work"]},{"week":12,"title":"Close","tasks":["Accept best organizational role or consulting project","Join APA Division 14 (I-O Psychology) or equivalent India body","Set Masters application goals if not yet pursuing","Build 5-year OD career plan"]}]',
