'[{"stage":"Entry","title":"Freelance Travel Writer","years":"0-2","salary":"₹2-6 LPA","responsibilities":["Article writing for travel publications","Photography basics","Pitch letters","Travel blogging"]},{"stage":"Mid","title":"Cultural Journalist / Documentary Researcher","years":"2-5","salary":"₹6-15 LPA","responsibilities":["Long-form features","Documentary research","Book writing","Platform collaborations"]},{"stage":"Senior","title":"Author / Documentary Producer","years":"5-10","salary":"₹15-40 LPA","responsibilities":["Book deals","Documentary production","Branded content","Speaking circuit"]},{"stage":"Leadership","title":"Media Brand / Production House Owner","years":"10+","salary":"₹40 LPA+","responsibilities":["Studio management","Streaming deals","Publishing relationships","Brand partnerships"]}]',
